import { saveBlobAsFile } from './downloadFile';

export const EXPORT_EMPTY = '-';

export const isExportUrl = (value) =>
  typeof value === 'string' && /^https?:\/\//i.test(value.trim());

export const formatExportValue = (value) => {
  if (value === null || value === undefined || value === '') {
    return EXPORT_EMPTY;
  }
  if (typeof value === 'boolean') {
    return value ? 'Yes' : 'No';
  }
  if (Array.isArray(value)) {
    const joined = value.filter((item) => item !== null && item !== undefined && item !== '').join('; ');
    return joined || EXPORT_EMPTY;
  }
  if (typeof value === 'object') {
    try {
      return JSON.stringify(value);
    } catch {
      return EXPORT_EMPTY;
    }
  }
  return String(value);
};

export const pickMediaUrl = (record, ...keys) => {
  if (!record) return EXPORT_EMPTY;
  for (const key of keys) {
    const value = record[key];
    if (typeof value === 'string' && value.trim()) {
      return value.trim();
    }
  }
  return EXPORT_EMPTY;
};

export const parseJsonField = (value) => {
  if (!value) return null;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

export const formatInstructionList = (items) => {
  if (!Array.isArray(items) || items.length === 0) return EXPORT_EMPTY;
  const filtered = items.filter((item) => item !== null && item !== undefined && String(item).trim() !== '');
  if (filtered.length === 0) return EXPORT_EMPTY;
  return filtered.map((item, index) => `${index + 1}. ${item}`).join(' | ');
};

export const formatExerciseInstructions = (instructions) => {
  const parsed = parseJsonField(instructions);
  if (!parsed) return { steps: EXPORT_EMPTY, dos: EXPORT_EMPTY };
  return {
    steps: formatInstructionList(parsed.steps),
    dos: formatInstructionList(parsed.dos),
  };
};

export const exportToCSV = (data, filename) => {
  if (!data || !data.length) {
    return;
  }

  const headers = Object.keys(data[0]);

  const csvContent = [
    headers.join(','),
    ...data.map((row) =>
      headers
        .map((header) => {
          const cellData = formatExportValue(row[header]);
          const escaped = cellData.replace(/"/g, '""');
          return `"${escaped}"`;
        })
        .join(','),
    ),
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  saveBlobAsFile(blob, `${filename || 'export'}.csv`);
};
