import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    Typography,
} from '@mui/material';
import BaseModal from '../BaseModal';
import FileUpload from '../FileUpload';

const GoalModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    initialData = null, 
    loading = false 
}) => {
    const isEdit = !!initialData;

    const [formData, setFormData] = useState({
        title: '',
        description: '',
        plan_duration: '',
        goal_weight: '',
        image_url: ''
    });

    useEffect(() => {
        if (open) {
            if (initialData) {
                setFormData({
                    title: initialData.title || '',
                    description: initialData.description || '',
                    plan_duration: initialData.plan_duration || '',
                    goal_weight: initialData.goal_weight != null ? String(initialData.goal_weight) : '',
                    // List/detail responses alias image_url -> image; support both.
                    image_url: initialData.image || initialData.image_url || ''
                });
            } else {
                setFormData({
                    title: '',
                    description: '',
                    plan_duration: '',
                    goal_weight: '',
                    image_url: ''
                });
            }
        }
    }, [open, initialData]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ 
            ...prev, 
            [name]: value 
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit(formData);
    };

    const actions = (
        <Box sx={{ 
            display: 'flex', 
            flexDirection: { xs: 'column-reverse', sm: 'row' },
            gap: 2, 
            mt: 4, 
            pt: 3, 
            borderTop: '1px solid #474747',
            width: '100%'
        }}>
            <Button 
                fullWidth 
                variant="outlined" 
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    height: 48, 
                    borderRadius: '12px',
                    textTransform: 'none',
                    fontWeight: 700,
                    borderColor: '#474747',
                    color: '#FFFFFF',
                    fontFamily: "'Montserrat', sans-serif",
                    '&:hover': {
                        borderColor: '#FFFFFF',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button 
                fullWidth 
                variant="contained" 
                onClick={handleSubmit}
                disabled={loading}
                sx={{ 
                    height: 48, 
                    borderRadius: '12px',
                    textTransform: 'none',
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    color: '#000000',
                    fontFamily: "'Montserrat', sans-serif",
                    '&:hover': {
                        bgcolor: '#3EB05D'
                    }
                }}
            >
                {loading ? 'Processing...' : (isEdit ? 'Update Goal' : 'Add Goal')}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={isEdit ? 'Edit Goal' : 'Add New Goal'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 2, 
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2.5,
                    width: '100%',
                }}
            >
                <TextField
                    fullWidth
                    label="Goal Title"
                    name="title"
                    value={formData.title}
                    onChange={handleChange}
                    required
                    placeholder="e.g. Weight Loss"
                />

               
                <TextField
                    fullWidth
                    multiline
                    rows={4}
                    label="Description"
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    placeholder="Describe the goal objective..."
                />

                <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, gap: 2.5 }}>
                    <TextField
                        fullWidth
                        label="Plan Duration"
                        name="plan_duration"
                        value={formData.plan_duration}
                        onChange={handleChange}
                        placeholder="e.g. 12 weeks"
                    />
                    <TextField
                        fullWidth
                        type="number"
                        label="Target Goal Weight (kg)"
                        name="goal_weight"
                        value={formData.goal_weight}
                        onChange={handleChange}
                        placeholder="e.g. 70"
                        inputProps={{ min: 0, step: '0.1' }}
                    />
                </Box>
                 <Box>
                    <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'block', textTransform: 'uppercase' }}>
                        Goal Image
                    </Typography>
                    <FileUpload 
                        folderName="goals"
                        maxSizeMB={10}
                        helperText="PNG, JPG or WEBP (max. 10MB)"
                        existingImageUrl={formData.image_url}
                        onUploadSuccess={(url) => setFormData(prev => ({ ...prev, image_url: url }))}
                        onRemove={() => setFormData(prev => ({ ...prev, image_url: '' }))}
                    />
                </Box>

            </Box>
        </BaseModal>
    );
};

export default GoalModal;

