import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
    Box, 
    Typography, 
    IconButton, 
    Tooltip,
    alpha,
    useTheme,
} from '@mui/material';
import { 
    Visibility as ViewIcon, 
    Edit as EditIcon, 
    Delete as DeleteIcon,
    TrackChanges as GoalIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import DataTable from '../../../components/DataTable';

import DetailsModal from '../../../components/DetailsModal';
import ConfirmationModal from '../../../components/ConfirmationModal';
import GoalModal from '../../../components/page_components/GoalModal';
import { toast } from 'react-hot-toast';
import { mapGoalExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import { useSelector } from 'react-redux';
import dayjs from 'dayjs';
import ImageView from '../../../components/ImageView';

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const Goals = () => {
    const theme = useTheme();
    const navigate = useNavigate();
    const [goals, setGoals] = useState([]);

    const [isLoading, setIsLoading] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(5);
    const [orderBy, setOrderBy] = useState('created_at');
    const [order, setOrder] = useState('desc');
    const [searchTerm, setSearchTerm] = useState('');

    const [openViewModal, setOpenViewModal] = useState(false);
    const [openDeleteModal, setOpenDeleteModal] = useState(false);
    const [openAddEditModal, setOpenAddEditModal] = useState(false);
    const [selectedGoal, setSelectedGoal] = useState(null);
    const [goalToDelete, setGoalToDelete] = useState(null);
    const [goalToEdit, setGoalToEdit] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const token = useSelector((state) => state.auth.token);


    const fetchGoals = useCallback(async (apiPage, limit) => {
        if (!token) return;
        setIsLoading(true);
        try {
            const params = {
                page: apiPage,
                limit: limit,
                sort_by: orderBy,
                sort_order: order,
            };

            if (searchTerm) {
                params.q = searchTerm;
            }

            const queryParams = new URLSearchParams(params);

            const res = await fetch(`${BASE_URL}/goals?${queryParams.toString()}`, {
                method: "GET",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
            });
            const json = await res.json();
            if (!res.ok || json.error) {
                toast.error(json.message || "Failed to fetch goals");
                return;
            }

            // Ultimate Robust Data Extraction
            let goalsArray = [];
            if (Array.isArray(json)) {
                goalsArray = json;
            } else if (json.data) {
                if (Array.isArray(json.data)) {
                    goalsArray = json.data;
                } else if (Array.isArray(json.data.goals)) {
                    goalsArray = json.data.goals;
                }
            } else if (Array.isArray(json.goals)) {
                goalsArray = json.goals;
            }

            setGoals(goalsArray);
            
            const total = json.pagination?.total || 
                          json.data?.pagination?.total || 
                          json.total || 
                          json.data?.total || 
                          goalsArray.length || 0;
            setTotalCount(total);
        } catch (err) {
            console.error("Error fetching goals:", err);
            toast.error("Something went wrong while fetching goals");
        } finally {
            setIsLoading(false);
        }
    }, [token, orderBy, order, searchTerm]);

    const handleExport = useCallback(async (dates, format) => {
        if (!token) return;
        setIsExporting(true);
        const toastId = toast.loading(`Exporting goals as ${format.toUpperCase()}...`);
        try {
            const params = {
                sort_by: orderBy,
                sort_order: order,
                not_pagination: "true",
                start_date: dates.startDate.format('YYYY-MM-DD'),
                end_date: dates.endDate.format('YYYY-MM-DD'),
            };

            if (searchTerm) {
                params.q = searchTerm;
            }

            const queryParams = new URLSearchParams(params);

            const res = await fetch(`${BASE_URL}/goals?${queryParams.toString()}`, {
                method: "GET",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
            });

            const json = await res.json();
            if (!res.ok || json.error) {
                throw new Error(json.message || "Failed to fetch goals for export");
            }

            const items = extractExportList(json, 'goals');
            const filename = `Goals_Report_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

            await performExport({
                items,
                mapper: mapGoalExport,
                format,
                filename,
                sheetName: 'Goals',
                entityName: 'goals',
                toastId,
            });
        } catch (err) {
            console.error("Export error:", err);
            toast.error(err.message || "Something went wrong while exporting", { id: toastId });
        } finally {
            setIsExporting(false);
        }
    }, [token, searchTerm, orderBy, order]);

    useEffect(() => {
        if (token) {
            fetchGoals(page + 1, rowsPerPage);
        }
    }, [page, rowsPerPage, fetchGoals, token]);

    const handleSortChange = (property) => {
        const isAsc = orderBy === property && order === 'asc';
        setOrder(isAsc ? 'desc' : 'asc');
        setOrderBy(property);
        setPage(0);
    };

    const handleViewDetails = (goal) => {
        setSelectedGoal(goal);
        setOpenViewModal(true);
    };

    const handleAddClick = () => {
        navigate('/goals/add');
    };


    const handleEditClick = (goal) => {
        setGoalToEdit(goal);
        setOpenAddEditModal(true);
    };

    const handleDeleteClick = (goal) => {
        setGoalToDelete(goal);
        setOpenDeleteModal(true);
    };

    const handleConfirmDelete = async () => {
        if (!goalToDelete || !token) return;
        setIsLoading(true);
        try {
            const res = await fetch(`${BASE_URL}/goals/${goalToDelete.id}`, {
                method: "DELETE",
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
            });
            const json = await res.json();
            if (!res.ok || json.error) {
                throw new Error(json.message || "Failed to delete goal");
            }
            toast.success('Goal Deleted Successfully!');
            fetchGoals(page + 1, rowsPerPage);
            setOpenDeleteModal(false);
            setGoalToDelete(null);
        } catch (err) {
            console.error("Delete error:", err);
            toast.error(err.message || "Something went wrong while deleting");
        } finally {
            setIsLoading(false);
        }
    };

    const handleSaveGoal = async (formData) => {
        if (!token) return;
        setIsSaving(true);
        try {
            const url = goalToEdit ? `${BASE_URL}/goals/${goalToEdit.id}` : `${BASE_URL}/goals`;
            const method = goalToEdit ? "PATCH" : "POST";
            
            const res = await fetch(url, {
                method: method,
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(formData),
            });
            const json = await res.json();
            if (!res.ok || json.error) {
                throw new Error(json.message || `Failed to ${goalToEdit ? 'update' : 'add'} goal`);
            }
            toast.success(`Goal ${goalToEdit ? 'Updated' : 'Added'} Successfully!`);
            fetchGoals(page + 1, rowsPerPage);
            setOpenAddEditModal(false);
            setGoalToEdit(null);
        } catch (err) {
            console.error("Save error:", err);
            toast.error(err.message || "Something went wrong while saving");
        } finally {
            setIsSaving(false);
        }
    };

    const columns = [
        {
            id: 'title',
            label: 'Goal Name',
            sortable: true,
            render: (row) => (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Box sx={{ 
                        width: 44, 
                        height: 44, 
                        borderRadius: '12px', 
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center',
                        bgcolor: alpha(theme.palette.primary.main, 0.1),
                        color: theme.palette.primary.main,
                        border: '1px solid rgba(255,255,255,0.05)',
                        overflow: 'hidden'
                    }}>
                        {row.image ? (
                            <ImageView 
                                src={row.image} 
                                sx={{ width: '100%', height: '100%', objectFit: 'cover' }} 
                            />
                        ) : (
                            <GoalIcon />
                        )}
                    </Box>
                    <Box>
                        <Typography sx={{ color: '#FFFFFF', fontWeight: 600, fontSize: '0.875rem' }}>
                            {row.title}
                        </Typography>
                    </Box>
                </Box>
            )
        },
        {
            id: 'description',
            label: 'Description',
            sortable: false,
            render: (row) => (
                <Typography sx={{ color: '#FFFFFF', fontSize: '0.875rem' }}>
                    {row.description ? (row.description.length > 80 ? row.description.substring(0, 80) + "..." : row.description) : "-"}
                </Typography>
            )
        },
        {
            id: 'plan_duration',
            label: 'Plan Duration',
            sortable: true,
            render: (row) => (
                <Typography sx={{ color: '#FFFFFF', fontSize: '0.875rem' }}>
                    {row.plan_duration || '-'}
                </Typography>
            )
        },
        {
            id: 'goal_weight',
            label: 'Target Weight',
            sortable: true,
            render: (row) => (
                <Typography sx={{ color: '#4CC66E', fontSize: '0.875rem', fontWeight: 600 }}>
                    {row.goal_weight != null && row.goal_weight !== '' ? `${row.goal_weight} kg` : '-'}
                </Typography>
            )
        },
        {
            id: 'created_at',
            label: 'Date Added',
            sortable: true,
            render: (row) => (
                <Typography sx={{ color: '#8B8D97', fontSize: '0.875rem' }}>
                    {row.created_at ? new Date(row.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '-'}
                </Typography>
            )
        },
        {
            id: 'actions',
            label: 'Actions',
            render: (row) => (
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Tooltip title="View Details">
                        <IconButton 
                            size="small" 
                            onClick={() => handleViewDetails(row)}
                            sx={{ color: '#9F6EDA', bgcolor: alpha('#9F6EDA', 0.1), '&:hover': { bgcolor: alpha('#9F6EDA', 0.2) } }}
                        >
                            <ViewIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Edit">
                        <IconButton 
                            size="small" 
                            onClick={() => handleEditClick(row)}
                            sx={{ color: '#9F6EDA', bgcolor: alpha('#9F6EDA', 0.1), '&:hover': { bgcolor: alpha('#9F6EDA', 0.2) } }}
                        >
                            <EditIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete">
                        <IconButton 
                            size="small" 
                            onClick={() => handleDeleteClick(row)}
                            sx={{ color: '#FF5050', bgcolor: alpha('#FF5050', 0.1), '&:hover': { bgcolor: alpha('#FF5050', 0.2) } }}
                        >
                            <DeleteIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </Box>
            )
        }
    ];

    const goalDetailsData = useMemo(() => {
        if (!selectedGoal) return [];
        return [
            { label: 'Goal Title', value: selectedGoal.title },
            { label: 'Plan Duration', value: selectedGoal.plan_duration || 'Not specified' },
            {
                label: 'Target Goal Weight',
                value: selectedGoal.goal_weight != null && selectedGoal.goal_weight !== '' ? `${selectedGoal.goal_weight} kg` : 'Not specified',
                color: '#4CC66E',
            },
            { label: 'Detailed Description', value: selectedGoal.description || 'No description provided', vertical: true },
            { label: 'Date Created', value: selectedGoal.created_at ? new Date(selectedGoal.created_at).toLocaleString() : 'N/A' },
            { label: 'Last Updated', value: selectedGoal.updated_at ? new Date(selectedGoal.updated_at).toLocaleString() : 'N/A' },
        ];
    }, [selectedGoal]);


    return (
        <Box sx={{ p: { xs: 1, md: 3 } }}>
            <DataTable
                title="Manage Goals"
                columns={columns}
                data={goals}
                isLoading={isLoading}
                onAddClick={handleAddClick}
                addLabel="Add Goal"
                onExport={handleExport}
                isExporting={isExporting}
                searchTerm={searchTerm}
                onSearchChange={(val) => {
                    setSearchTerm(val);
                    setPage(0);
                }}
                orderBy={orderBy}
                order={order}
                onSortChange={handleSortChange}
                pagination={{
                    page: page,
                    rowsPerPage: rowsPerPage,
                    totalCount: totalCount,
                    onPageChange: (_, newPage) => setPage(newPage),
                    onRowsPerPageChange: (e) => {
                        setRowsPerPage(parseInt(e.target.value, 10));
                        setPage(0);
                    }
                }}
                onEditClick={handleEditClick}
                emptyTitle="No goals found"
                
            />

            {selectedGoal && (
                <DetailsModal
                    open={openViewModal}
                    onClose={() => setOpenViewModal(false)}
                    title="Goal Details"
                    data={goalDetailsData}
                    maxWidth="sm"
                >
                    {selectedGoal.image && (
                        <Box sx={{ mt: 3, borderRadius: '16px', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.1)' }}>
                            <ImageView 
                                src={selectedGoal.image} 
                                sx={{ width: '100%', height: '250px', objectFit: 'cover' }} 
                            />
                        </Box>
                    )}
                </DetailsModal>
            )}

            <GoalModal
                open={openAddEditModal}
                onClose={() => setOpenAddEditModal(false)}
                onSubmit={handleSaveGoal}
                initialData={goalToEdit}
                loading={isSaving}
            />

            <ConfirmationModal
                open={openDeleteModal}
                onClose={() => setOpenDeleteModal(false)}
                onConfirm={handleConfirmDelete}
                title="Delete Goal?"
                message={`Are you sure you want to delete "${goalToDelete?.title}"? This action cannot be undone.`}
                confirmText="Delete"
                confirmColor="error"
                loading={isLoading}
            />
        </Box>
    );
};

export default Goals;
