import React from 'react';
import {
    Box,
    Stack,
    Typography,
    Divider,
    useTheme,
    alpha,
    CircularProgress
} from '@mui/material';
import BaseModal from './BaseModal';

const DetailsModal = ({
    open,
    onClose,
    title,
    data = [],
    isLoading = false,
    maxWidth = 'sm',
    showDividers = true,
    children,
    actions
}) => {
    const theme = useTheme();

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={title}
            maxWidth={maxWidth}
            actions={actions}
        >
            <Stack spacing={0} sx={{ position: 'relative', minHeight: isLoading ? '200px' : 'auto' }}>
                {isLoading ? (
                    <Box sx={{
                        position: 'absolute',
                        inset: 0,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 1
                    }}>
                        <CircularProgress size={40} />
                    </Box>
                ) : (
                    data.map((item, index) => (
                    <Box
                        key={index}
                        sx={{
                            display: item.vertical ? 'block' : 'flex',
                            justifyContent: 'space-between',
                            alignItems: item.vertical ? 'flex-start' : 'center',
                            py: 2,
                            px: 1,
                            gap: 2,
                            borderRadius: '12px',
                            transition: 'all 0.2s ease',
                            borderBottom: showDividers && index !== data.length - 1 
                                ? '1px solid rgba(255, 255, 255, 0.05)' 
                                : 'none',
                            '&:hover': {
                                bgcolor: 'rgba(255, 255, 255, 0.02)',
                            },
                        }}
                    >
                        <Box sx={{ minWidth: item.vertical ? '100%' : '40%', mb: item.vertical ? 0.5 : 0 }}>
                            <Typography
                                variant="caption"
                                sx={{
                                    fontWeight: 700,
                                    color: '#8B8D97',
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.5px',
                                    fontSize: '0.7rem'
                                }}
                            >
                                {item.label}
                            </Typography>
                        </Box>
                        
                        <Box
                            sx={{
                                flex: 1,
                                textAlign: item.vertical ? 'left' : 'right',
                                display: 'flex',
                                justifyContent: item.vertical ? 'flex-start' : 'flex-end',
                                alignItems: 'center'
                            }}
                        >
                            {typeof item.value === 'string' || typeof item.value === 'number' ? (
                                <Typography
                                    variant="body2"
                                    sx={{
                                        color: item.color || '#FFFFFF',
                                        wordBreak: 'break-word',
                                        fontWeight: 600,
                                        fontSize: '0.95rem'
                                    }}
                                >
                                    {item.value}
                                </Typography>
                            ) : (
                                <Box sx={{ width: '100%', display: 'flex', justifyContent: item.vertical ? 'flex-start' : 'flex-end' }}>
                                    {item.value}
                                </Box>
                            )}
                        </Box>
                    </Box>
                    ))
                )}
            </Stack>
            
            {children && !isLoading && (
                <Box 
                    sx={{ 
                        mt: 2, 
                        pt: 2, 
                        borderTop: showDividers && data.length > 0 
                            ? '1px solid rgba(255, 255, 255, 0.05)' 
                            : 'none' 
                    }}
                >
                    {children}
                </Box>
            )}
        </BaseModal>
    );
};

export default DetailsModal;
